          'R2 Air: temperature and humidity at 1.8 m in a passive shield, ± 0.4 °C and ± 3 % RH, sampled at the same cadence as the water level so the two can be joined without interpolation.',
          'R3 Cadence: four readings per hour, timestamped to UTC, buffered for 14 days. A surge takes the network link down; the buffer is what makes the event readable afterwards.',
