          'Failure in a harbour is rarely dramatic. The first thing to go is the pressure port: a film of salt bridges the port, the reading flattens, and the node keeps reporting a plausible number for weeks. That is worse than going dark, because it looks like data.',
          'The second failure is the gland. A single UV-degraded cable gland admits a teaspoon of water, which sits under the board and corrodes the first thing it touches — usually the antenna feed, so the node goes quiet and the port stays clean. Two different failures, one symptom, and no way to tell them apart from the back end.',
          'The third is the battery, and it is a design decision rather than an accident: a pack that lasts three years is a pack nobody services. We specify a one-year interval and a physical tag on the mast, because a scheduled visit that finds nothing is cheaper than an unscheduled one that finds water.',
