          'The schedule is built backwards from the first sale at 7:30: 200 loaves need four hours of mixing and folding, 90 minutes of proof and 55 minutes in the oven in three loads. That puts the first mix at 02:40 and the last bake out at 07:10, which leaves twenty minutes of slack — the only slack in the day.',
          'Sixty kilos of dough a day is the ceiling for one mixer and one baker. At 220 loaves we would need a second mixer or a night shift, and both cost more than the extra twenty loaves earn. The ceiling is a business decision disguised as a kitchen constraint.',
          'Waste in week one ran at 16 % and settled at 6.1 % by week four, once the afternoon bake was cut to a third of the morning batch. Every bakery we asked said the same thing: the second bake is where the waste lives, and it is also the only thing customers ask for by name.',
