          'Growth in a workshop of this size arrives as a contract, not as a curve. The two offers we declined in May and September would each have doubled our monthly output for twelve months, and each would have required a second shift, a second finishing room and a foreman we did not have. We costed both at 14 % margin and thirty months of disruption.',
          'What we did instead was narrower and less photogenic: we rebuilt the finish room so two people can work in it without moving each other, we bought a second bandsaw rather than a bigger one, and we hired two apprentices in September instead of a production manager in June.',
