          '这笔电费也值得说：1.5 kW 的泵一天运行约 72 分钟，用电 1.8 度；但因为频繁启停，启动电流是额定值的 6 倍，实际耗电约 2.6 度/天，一年多花 200 度。听起来不多，可这套泵已经跑了 13 年——当年选型时按「3 台泵轮换」设计的，实际只装了一台，另外两台的位子一直空着。',
          '顺带把水箱和泵的关系说明白：泵从市政管网抽水，先打到屋顶水箱，水箱再往下供。也就是说，泵的角色只是「把水搬上去」，稳定压力靠的是水箱的高度。8 层楼高 24 米，理论上屋顶水箱往下应有 0.24 MPa，实测到八层只有 0.06——中间那 0.18 丢在 1998 年的立管和六个锈弯头里，跟泵一点关系都没有。',
          '水箱是另一笔账。12 立方米的不锈钢拼装水箱，2013 年装的，按规范每半年清洗一次、每两年做一次水质检测。实际是 2023 年 4 月之后没再洗过，检测报告一份都没有。掀开人孔盖能看见水面一层薄膜，池底沉积 3–5 厘米——这不是物业管理疏忽那么简单，是 2024 年换物业时，交接清单里根本没有「二次供水」这一项。',
