          'The street is quiet by ordinary standards. In the week before the works started, the meter on the front wall of No. 14 read 47 dB(A) during the day and 38 at night — the sound of a residential road with a bus route at one end.',
          'In week four it read 78 dB(A) for the hour to 11:00. The guideline for the outside of a dwelling is 55 in the day and 45 at night. Inside the bedroom of No. 31, with the window shut, the meter read 63 — against a night-time target of 30.',
          'The numbers did not come from the piling. The rig stood 62 metres away, behind the depot wall, and contributed four or five decibels at most. They came from a hydraulic breaker working eighteen metres from the back of the terrace, from reversing alarms that sound at 108 dB one metre from the vehicle, and from a hoarding two metres high that nobody could be shielded by above the ground floor.',
          'The council served a notice under section 60 of the Control of Pollution Act on day nineteen. The developer agreed four measures on 25 September, worth £59,500 — 0.45 per cent of a £13.2 million scheme. By week eight the facade read 71 and the bedroom 41.',
          'The terrace is not unusual. Ashgrove is one of eleven streets in the borough with a site inside fifty metres, and the council has two environmental health officers for all of them. What made this case different was organisational: a residents’ group that started logging complaints in a shared spreadsheet in week one, and a developer who agreed to fund independent monitoring in week five. Neither of those is acoustics.',
          'Two things were measured that nobody had asked about. The lunch break, 12:30 to 13:15, when the site went quiet and the street read 46 — its old self, for forty-five minutes a day. And the four seconds after each lorry left the gate, which residents named as the worst part of the day, because it was the only moment they could hear anything else.',
          'Nine weeks of data is a lot of evidence for one street, and most of it is dull. The meter wrote 8 640 readings an hour, and for 71 per cent of the period the street was under 55 dB(A). This report is about the other 29 per cent, because that is the part that kept people awake.',
          'One caveat belongs at the front rather than the back. Every figure here is dB(A), the weighting that discounts low frequency to match the ear at moderate levels. It does not match the ear at 78. The 31.5 Hz band during breaking measured 84 dB(Z), and eight households said their windows rattled. What follows uses dB(A) because that is what the consent is written in, and says so each time it matters.',
