          'The first meter went up on 3 August, a week before anything started. That week is the only honest comparison in this report: 47 dB(A) in the day, 38 at night, with the depot empty and the gates chained. Everything after it is measured against a street that no longer exists.',
          'Three positions were used. One on the front wall of No. 14 at 1.8 metres, closest to the depot gate and the noisiest point on the terrace. One in the rear courtyard at 4.2 metres, the height of a first-floor window. One inside the bedroom of No. 31 at 1.2 metres from the glass, with the window closed. A fourth meter was borrowed for two afternoons to repeat the indoor measurement with the window open.',
          'Each meter logged one-second LAeq, LAFmax and LAZ, indoors and out, twenty-four hours a day, into a logger in a steel box chained to the railing. The three meters produced 5.4 million samples — 71 megabytes, mostly of a quiet street. Hourly LAeq was computed afterwards, from the same raw data, so that any hour in this report can be re-run.',
          'What a meter cannot do is decide whether the noise is a nuisance. The guidance asks two questions: is the absolute level too high, and is the increase over the existing background too large? Here the second question answers itself. A 31 dB increase over 47 is not a marginal case; it is a different street.',
          'Two precautions are worth stating. Rain days were excluded (two of them) and so were hours with wind above 5 m/s, because both corrupt the reading rather than raise it. The meters were calibrated at 94.0 dB before and after the period; drift was 0.3 dB across nine weeks, which is inside the tolerance of a class 1 instrument and outside anything discussed in this report.',
          'The limitations are just as real. A single point cannot separate sources, so attribution here relies on the Z-weighted spectrum and on timing: the breaker is impulsive and runs in twenty-minute bursts, the piling rig is continuous for hours, the alarms are tonal and repeat every three seconds. Those three signatures are distinguishable in the data without anyone standing in the street with a clipboard.',
