          'Six machines worked on the site. A hydraulic breaker on the slab, rated 100 dB at seven metres. A rotary piling rig, 92 dB at ten. Two telehandlers with reversing alarms, 108 dB at one. A concrete pump, and enough angle grinders to fill the gaps between them.',
          'The hoarding is the part that should have worked and did not. It is 2.1 metres of plywood on the depot boundary, eighteen metres from the rear wall — built to keep people out, which it does. A barrier only casts an acoustic shadow above the line of sight from the receiver over its top edge. From the ground floor that shadow starts at about 2.4 metres of height; from the second floor, at 6.8. Above that, the street heard the site directly, and the street is four storeys of windows on that side.',
          'Frequency explains the rest of the gap between 78 on the meter and “unbearable” in the interviews. The breaker’s energy sits between 63 and 250 Hz; the alarms between 1 and 2 kHz. The A-weighting discounts everything below 500 Hz — 3 dB at 250, 16 at 63, 39 at 31.5. A meter reading 78 dB(A) can sit on top of a low-frequency event 20 dB louder than the number suggests.',
          'The low frequency was measurable. During breaking, the 31.5 Hz band read 84 dB(Z) in the courtyard; windows in eight flats rattled at the same moments, and two residents reported crockery moving on shelves. There is no limit for 31.5 Hz in the consent, which is not the same as saying there is no problem — it is saying the document was not written to see it.',
          'The attribution holds up. Sixty-one per cent of complaints mention banging, 22 per cent beeping, 11 per cent engines, 6 per cent dust. Nothing in the log points at the piling rig — the machine the contractor spent money on: £4,000 for a damped hammer, 62 metres away and behind a wall.',
          'That is the mistake worth remembering. A noise budget gets spent where the meter reads loudest during a site visit, and a site visit happens when someone is free to make it — mid-morning, near the gate, beside the loudest thing. The distribution of complaints is a better map of a site than the distribution of decibels.',
