          'The tenancy began in October 2022. The field had been under a silage regime since the 1970s: a first cut in late May, a second in early July, a third in September if the season allowed, and 250 kilograms of nitrogen a hectare every spring. In 2022 that produced 41.6 tonnes of fresh grass, which the previous tenant fed to cattle two miles down the valley.',
          'Nothing in that field flowered and set seed. The first cut came before the grasses headed, the fertiliser favoured the two or three species that respond to it, and what did come through — docks, chickweed, the odd thistle — was what tolerates being driven over. By August the field was a lawn with a crop on it.',
          'The 2023 baseline found a mean of 6.1 species per square metre in the five fields and 53 species across the site. Two-thirds of those records came from the hedge bottom, the pond edge and the strip under the fence: less than a fifth of the area, and the only part that had ever been left alone.',
