          'Fields C to F had no seed and no rattle. They gained anyway — 8 to 22, 11 to 27, 7 to 18, 6 to 15 — but the gain is concentrated within thirty metres of a hedge or a ditch, and the middles of the two largest fields are still ryegrass, at a mean of seven species per square metre.',
